Sql:
SELECT tblClientServiceNeeds.ClientID, tblClientServicePlan.FiscalYear, tblClientServicePlan.AnnualEstCost, tblClientServicePlan.ClientServicePlanID
FROM tblClientServicePlan INNER JOIN tblClientServiceNeeds ON tblClientServicePlan.ClientServiceNeedID = tblClientServiceNeeds.ClientServiceNeedID
WHERE tblClientServicePlan.Status = 'Approved';
